import 'package:cloud_firestore/cloud_firestore.dart';
class ConversationModel { const ConversationModel({required this.id,required this.participantIds,this.lastMessage='',this.unreadCounts=const {},this.typingUserIds=const [],this.updatedAt}); final String id,lastMessage; final List<String> participantIds,typingUserIds; final Map<String,int> unreadCounts; final DateTime? updatedAt; factory ConversationModel.fromFirestore(DocumentSnapshot<Map<String,dynamic>> doc){final map=doc.data() ?? const {}; return ConversationModel(id:doc.id,participantIds:List<String>.from(map['participantIds'] as List? ?? const []),lastMessage:map['lastMessage'] as String? ?? '',typingUserIds:List<String>.from(map['typingUserIds'] as List? ?? const []),unreadCounts:(map['unreadCounts'] as Map<String,dynamic>? ?? const {}).map((k,v)=>MapEntry(k,(v as num).toInt())),updatedAt:(map['updatedAt'] as Timestamp?)?.toDate());} }
